 public static int Run(string output){Directory.CreateDirectory(output);var checks=new List<string>();void Assert(bool value,string why){if(!value)throw new Exception(why);checks.Add(why);}var secrets=new TestSecrets();var store=new AiSettingsStore(Path.Combine(output,"ai-connections.json"));foreach(var profile in store.Profiles.ToArray()){store.Save(profile with{Model=profile.Provider==AiProvider.OpenAI?"text-fixture":"claude-text-fixture"});secrets.Write(profile.Id,"AiApiKey","fixture-key-"+profile.Provider);}using var handler=new ProviderFixture();using var http=new HttpClient(handler);using var api=new AiProviderClient(secrets,http);
