sert(exited,"Canceled CLI request leaves no owned child");using var bound=new CancellationTokenSource(TimeSpan.FromSeconds(10));bool oversized=false;try{await AiCodexClient.Run(Environment.ProcessPath!,["--ai-cli-fixture","oversized"],null,directory,bound.Token);}catch(InvalidDataException){oversized=true;}Assert(oversized,"Oversized CLI output stops its child without waiting for timeout");}).GetAwaiter().GetResult();
