   var providers=ai.GetVisualDescendants().OfType<ComboBox>().Single(c=>c.Name=="AiProvider");providers.SelectedItem=providers.Items.OfType<AiConnectionProfile>().Single(p=>p.Provider==AiProvider.Anthropic);Pump();question.Text="Draft Claude tasks";Click(ai,"Review and Send");Click(ai.OwnedWindows.OfType<McpReviewWindow>().Single(),"Send Request");WaitUntil(()=>ai.GetVisualDescendants().OfType<TextBlock>().Any(t=>t.Text?.Contains("Input 20 / Output 30")==true));Assert(handler.LastProvider==AiProvider.Anthropic,"Native Claude UI connection "+theme);Click(ai,"Connection Settings");var editor=ai.OwnedWindows.OfType<AiConnectionEditor>().Single();using(var frame=editor.CaptureRenderedFrame()??throw new Exception("Settings frame missing"))frame.Save(Path.Combine(output,"planora-connection-"+theme+".png"));var mode=editor.GetVisualDescendants().OfType<ComboBox>().Single(c=>c.Name=="AiMode");Assert(!mode.Items.OfType<AiConnectionMode>().Contains(AiConnectionMode.CodexSubscription),"Claude settings show supported modes only "+theme);mode.SelectedItem=AiConnectionMode.Browser;Click(editor,"Save Connection");WaitUntil(()=>question.IsEnabled&&!ai.OwnedWindows.Any(),"web connection save");question.Text="Draft one web task";before=handler.Calls;Click(ai,"Review and Send");WaitUntil(()=>ai.OwnedWindows.OfType<McpReviewWindow>().Any(),"browser review");Click(ai.OwnedWindows.OfType<McpReviewWindow>().Single(),"Copy and Open");WaitUntil(()=>opened!=null,"browser handoff");Assert(opened!.Host=="claude.ai"&&handler.Calls==before,"Claude subscription uses browser handoff without API call "+theme);Assert(ai.Clipboard!.TryGetTextAsync().GetAwaiter().GetResult()?.Contains("Draft one web task")==true,"Reviewed prompt copied for web subscription "+theme);WaitUntil(()=>question.IsEnabled);Click(ai,"Paste Web Answer");WaitUntil(()=>ai.OwnedWindows.Any());var paste=ai.OwnedWindows.Single(w=>w.GetVisualDescendants().OfType<TextBox>().Any(t=>t.Name=="WebAnswer"));paste.GetVisualDescendants().OfType<TextBox>().Single(t=>t.Name=="WebAnswer").Text="{\"tasks\":[{\"name\":\"Web task\",\"duration\":\"2d\"}]}";Click(paste,"Use Answer");WaitUntil(()=>question.IsEnabled&&!ai.OwnedWindows.Any());Click(ai,"Import Task Draft");Click(ai.OwnedWindows.OfType<McpTaskImportWindow>().Single(),"Import Tasks");WaitUntil(()=>document.Tasks.Count==2);Assert(document.Tasks.Last().Name=="Web task","Web subscription draft is reviewable/importable "+theme);document.Undo();owner.RefreshForValidation();store.Save(store.Profiles.Single(p=>p.Provider==AiProvider.Anthropic) with{Mode=AiConnectionMode.Api});ai.Close();WaitUntil(()=>!ai.IsVisible);owner.SelectPreviewTab(1);Pump();using(var frame=owner.CaptureRenderedFrame()??throw new Exception("Main frame missing"))frame.Save(Path.Combine(output,"planora-main-"+theme+".png"));}
