   string fake=Path.GetFullPath(Path.Combine(output,"codex-discovery-"+Guid.NewGuid()));string arch=System.Runtime.InteropServices.RuntimeInformation.OSArchitecture==System.Runtime.InteropServices.Architecture.Arm64?"arm64":"x64";string triple=OperatingSystem.IsMacOS()?(arch=="arm64"?"aarch64":"x86_64")+"-apple-darwin":(arch=="arm64"?"aarch64":"x86_64")+"-unknown-linux-musl";
   string package=Path.Combine(fake,"lib","node_modules","@openai","codex");string native=Path.Combine(package,"node_modules","@openai",(OperatingSystem.IsMacOS()?"codex-darwin-":"codex-linux-")+arch,"vendor",triple,"bin","codex");string bin=Path.Combine(fake,"bin");
