 private static void Pump(){Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick(3);Dispatcher.UIThread.RunJobs();}
 private static void WaitUntil(Func<bool> ready,string reason="UI completion"){var timer=System.Diagnostics.Stopwatch.StartNew();while(!ready()){Pump();Thread.Sleep(10);if(timer.Elapsed>TimeSpan.FromSeconds(15))throw new TimeoutException("AI UI did not finish: "+reason);}Pump();}
 private static void Click(Window window,string text){window.GetVisualDescendants().OfType<Button>().Single(b=>Equals(b.Content,text)).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
 public sealed class TestSecrets:IMcpSecrets {private readonly Dictionary<string,string> _values=[];public string? Read(string id,string name)=>_values.GetValueOrDefault(id+"/"+name);public void Write(string id,string name,string value)=>_values[id+"/"+name]=value;public void Remove(string id,string name)=>_values.Remove(id+"/"+name);}
 private sealed class ProviderFixture:HttpMessageHandler {
  public int Calls;public string? LastBody;public AiProvider LastProvider;public bool HeadersCorrect,Slow;public HttpStatusCode Status=HttpStatusCode.OK;
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){if(Slow)await Task.Delay(Timeout.Infinite,token);if(request.RequestUri!.Host is not ("api.openai.com" or "api.anthropic.com"))throw new Exception("Unexpected endpoint");LastProvider=request.RequestUri.Host=="api.openai.com"?AiProvider.OpenAI:AiProvider.Anthropic;HeadersCorrect=LastProvider==AiProvider.OpenAI?request.Headers.Authorization?.ToString()=="Bearer fixture-key-OpenAI":request.Headers.GetValues("x-api-key").Single()=="fixture-key-Anthropic"&&request.Headers.GetValues("anthropic-version").Single()=="2023-06-01";if(Status!=HttpStatusCode.OK)return new(Status);object data;if(request.Method==HttpMethod.Get)data=new{data=new[]{new{id="text-fixture"},new{id="claude-text-fixture"}},has_more=false};else{Calls++;LastBody=await request.Content!.ReadAsStringAsync(token);string answer=JsonSerializer.Serialize(new{tasks=new[]{new{name="Draft scope",duration="2d"},new{name="Build first version",duration="5d"},new{name="Review delivery",duration="1d"}}});data=LastProvider==AiProvider.OpenAI?new{model="text-fixture",status="completed",output=new[]{new{type="message",content=new[]{new{type="output_text",text=answer}}}},usage=new{input_tokens=20,output_tokens=30}}:(object)new{model="claude-text-fixture",content=new[]{new{type="text",text=answer}},stop_reason="end_turn",usage=new{input_tokens=20,output_tokens=30}};}return new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(data),Encoding.UTF8,"application/json")};}
